import{at as e,it as t,n,vt as r}from"./chunks/framework.BtDTgfNe.js";var i=JSON.parse(`{"title":"Directives - v6","description":"Learn about different directives in Textwire, including @if, @each, @for, @insert, @component and more","frontmatter":{"title":"Directives - v6","description":"Learn about different directives in Textwire, including @if, @each, @for, @insert, @component and more"},"headers":[],"relativePath":"language-elements/directives.md","filePath":"src/language-elements/directives.md","lastUpdated":1795450043000}`),a={name:`language-elements/directives.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="directives" tabindex="-1">Directives <a class="header-anchor" href="#directives" aria-label="Permalink to “Directives”">​</a></h1><p>Textwire directives provide control over your templates through commands that begin with <code>@</code>. These directives enable you to conditionally display content, iterate over data, create reusable layouts, and build modular components. Each directive serves a specific purpose in the template rendering process, allowing you to write dynamic and maintainable templates without mixing complex logic into your presentation layer.</p><ul><li><a href="/language-elements/directives/if">@if</a> <code>@if(x == 1)</code></li><li><a href="/language-elements/directives/use">@use</a> <code>@use(&quot;layouts/main&quot;)</code></li><li><a href="/language-elements/directives/insert">@insert</a> <code>@insert(&quot;title&quot;, &quot;Home&quot;)</code></li><li><a href="/language-elements/directives/reserve">@reserve</a> <code>@reserve(&quot;title&quot;)</code></li><li><a href="/language-elements/directives/for">@for</a> <code>@for(i = 0; i &lt; 2; i++)</code></li><li><a href="/language-elements/directives/each">@each</a> <code>@each(name in names)</code></li><li><a href="/language-elements/directives/component">@component</a> <code>@component(&quot;components/post-card&quot;)@end</code></li><li><a href="/language-elements/directives/slot">@slot</a> <code>@slot(&#39;footer&#39;)</code></li><li><a href="/language-elements/directives/pass">@pass</a> <code>@pass(&#39;footer&#39;)@end</code></li><li><a href="/language-elements/directives/passif">@passif</a> <code>@passif(true, &#39;footer&#39;)@end</code></li><li><a href="/language-elements/directives/dump">@dump</a> <code>@dump(users, page)</code></li></ul><h2 id="reserved-names" tabindex="-1">Reserved Names <a class="header-anchor" href="#reserved-names" aria-label="Permalink to “Reserved Names”">​</a></h2><p>Directive names are reserved keywords. If you need to use one of them as plain text, for example in an email address, escape it with a backslash. Read more about <a href="/language-elements/syntax#escaping">escaping</a>.</p><p>For example, <code>me@username.com</code> results in the error <code>syntax error: expected &#39;(&#39; but found &#39;rname.com&#39;</code>, because <a href="/language-elements/directives/use">@use</a> is a reserved directive. Escape it like this: <code>me\\@username.com</code> to get <code>me@username.com</code>.</p>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};